package com.highpass.runspot.community.service;import com.highpass.runspot.community.domain.Post;import java.time.Duration;import lombok.RequiredArgsConstructor;import org.springframework.dao.DataAccessException;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class PostViewService{private final StringRedisTemplate redis;public void increase(Post post,Long userId){if(userId==null){post.increaseViewCount();return;}try{Boolean first=redis.opsForValue().setIfAbsent("post:view:"+post.getId()+":"+userId,"1",Duration.ofHours(24));if(Boolean.TRUE.equals(first))post.increaseViewCount();}catch(DataAccessException e){post.increaseViewCount();}}}
